// Filter articles by age and content quality
const now = new Date();
const maxAgeHours = 48;
const minAgeHours = 1;

// Filter by publication date
const filteredItems = $input.all().filter(item => {
  const pubDate = new Date(item.json.pubDate || item.json.isoDate);
  const ageHours = (now - pubDate) / (1000 * 60 * 60);

  // Check if article is within acceptable age range
  if (ageHours < minAgeHours || ageHours > maxAgeHours) {
    return false;
  }

  // Check for excluded keywords
  const title = (item.json.title || '').toLowerCase();
  const description = (item.json.description || '').toLowerCase();
  const content = title + ' ' + description;

  const excludeKeywords = ['sponsored', 'advertisement', 'promoted', 'advertorial'];
  if (excludeKeywords.some(keyword => content.includes(keyword))) {
    return false;
  }

  // Check for included keywords
  const includeKeywords = ['ai', 'artificial intelligence', 'machine learning', 'startup', 'innovation', 'technology', 'business', 'entrepreneurship'];
  if (!includeKeywords.some(keyword => content.includes(keyword))) {
    return false;
  }

  return true;
});

// Limit to top 10 articles
return filteredItems.slice(0, 10);

